-- 18.6 verifies a primary key's NOT NULL after it builds the index, so an oversized key in
-- one row is refused `54000` ahead of another row's NULL.
-- @setup
CREATE TABLE t (a text);
INSERT INTO t VALUES (NULL), ('');
-- @test
-- @expect-error: the item limit before the NULL
-- @expect-message
-- @profile-lock
ALTER TABLE t ADD PRIMARY KEY (a);
